contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address vault, address asset) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint256 firstRate;
        bool firstOk;

        uint256 r = c.rate(vault, asset); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstOk = false;
        } else {
            firstRate = r;
            firstOk = true;
        }

        uint256 balanceBefore = address(this).balance;

        uint256 secondRate;
        bool secondOk;

        uint256 r2 = c.rate(vault, asset); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondOk = false;
        } else {
            secondRate = r2;
            secondOk = true;
        }

        // General rule: if the first rate call succeeds, the second one must also succeed
        // and rate never moves native currency, so the test contract's balance is unchanged.
        assert(!firstOk || (secondOk && address(this).balance == balanceBefore));
    }

    receive() external payable {}
}

