// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    VaultAdapter c;

    function setUp() public {
        c = new VaultAdapter();
    }

    function _run(address vault, address asset) internal {
        vm.deal(address(c), VALUE_CAP);
        uint256 firstRate;
        bool firstOk;
        try c.rate(vault, asset) returns (uint256 r) {
            firstRate = r;
            firstOk = true;
        } catch {
            firstOk = false;
        }
        uint256 balanceBefore = address(this).balance;
        uint256 secondRate;
        bool secondOk;
        try c.rate(vault, asset) returns (uint256 r2) {
            secondRate = r2;
            secondOk = true;
        } catch {
            secondOk = false;
        }
        assertTrue(!firstOk || (secondOk && address(this).balance == balanceBefore));
    }

    function testFuzz_run(address vault, address asset) public {
        vm.assume(vault.code.length == 0 && uint160(vault) > 0xffff && vault != address(this) && vault != address(c) && vault != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && vault != 0x000000000000000000636F6e736F6c652e6c6f67 && vault != 0x4e59b44847b379578588920cA78FbF26c0B4956C && vault != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(asset.code.length == 0 && uint160(asset) > 0xffff && asset != address(this) && asset != address(c) && asset != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && asset != 0x000000000000000000636F6e736F6c652e6c6f67 && asset != 0x4e59b44847b379578588920cA78FbF26c0B4956C && asset != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(vault, asset);
    }

    receive() external payable {}
}
